use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Where the scanner is in the line.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between tokens: the next thing is a timestamp, a key, a word or an error.
    Start,
    /// Right after a `=`: the next thing is a value.
    Value,
    /// Past the end of the line or after an error: nothing more is yielded.
    Done,
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Start }
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

/// One scan result: a token and the offset scanning resumes at.
type Scanned<'a> = Result<(Token<'a>, usize), LexError>;

impl<'a> Iterator for Tokens<'a> {
    type Item = Result<Token<'a>, LexError>;

    fn next(&mut self) -> Option<Self::Item> {
        let scanned = match self.state {
            State::Start => scan_start(self.src, self.pos)?,
            State::Value => scan_value(self.src, self.pos),
            State::Done => return None,
        };
        match scanned {
            Ok((token, resume)) => {
                self.state = match token {
                    Token::Key(_) => State::Value,
                    _ => State::Start,
                };
                self.pos = resume;
                Some(Ok(token))
            }
            Err(error) => {
                self.state = State::Done;
                Some(Err(error))
            }
        }
    }
}

/// Scans the token at the first non-blank byte from `from`. `None` at the end of the line.
fn scan_start(src: &str, from: usize) -> Option<Scanned<'_>> {
    let b = src.as_bytes();
    let p = skip_blanks(b, from);
    let scanned = match *b.get(p)? {
        b'[' => scan_timestamp(src, p),
        b'"' => Err(LexError::UnexpectedQuote { pos: p }),
        b'=' => Err(LexError::EmptyKey { pos: p }),
        _ => scan_key_or_word(src, p),
    };
    Some(scanned)
}

/// Scans the value that follows a `=`, which is empty when a blank or the end comes first.
fn scan_value(src: &str, p: usize) -> Scanned<'_> {
    let b = src.as_bytes();
    match b.get(p).copied() {
        None => Ok((Token::Bare(&src[p..p]), p)),
        Some(c) if is_blank(c) => Ok((Token::Bare(&src[p..p]), p)),
        Some(b'"') => scan_quoted(src, p),
        Some(_) => {
            let end = run_until(b, p, is_blank)?;
            Ok((Token::Bare(&src[p..end]), end))
        }
    }
}

/// Scans `[...]` where `open` is the index of the `[`.
fn scan_timestamp(src: &str, open: usize) -> Scanned<'_> {
    let b = src.as_bytes();
    let start = open + 1;
    let mut close = start;
    loop {
        match b.get(close).copied() {
            None => return Err(LexError::UnterminatedTimestamp { pos: open }),
            Some(b']') => break,
            Some(b'[') => return Err(LexError::NestedBracket { pos: close }),
            Some(_) => close += 1,
        }
    }
    expect_separator(b, close + 1)?;
    Ok((Token::Timestamp(&src[start..close]), close + 1))
}

/// Scans `"..."` where `open` is the index of the opening quote.
fn scan_quoted(src: &str, open: usize) -> Scanned<'_> {
    let b = src.as_bytes();
    let start = open + 1;
    let close = find_closing_quote(b, start, open)?;
    expect_separator(b, close + 1)?;
    Ok((Token::Quoted(&src[start..close]), close + 1))
}

/// Finds the quote that ends a quoted value, stepping over each valid escape pair.
fn find_closing_quote(b: &[u8], start: usize, open: usize) -> Result<usize, LexError> {
    let mut i = start;
    loop {
        match b.get(i).copied() {
            None => return Err(LexError::UnterminatedQuote { pos: open }),
            Some(b'"') => return Ok(i),
            Some(b'\\') => match b.get(i + 1).copied() {
                None => return Err(LexError::UnterminatedQuote { pos: open }),
                Some(b'"' | b'\\' | b'n' | b't') => i += 2,
                Some(_) => return Err(LexError::InvalidEscape { pos: i }),
            },
            Some(_) => i += 1,
        }
    }
}

/// Scans a run that ends at a `=` (a key) or at a blank or the end (a word).
fn scan_key_or_word(src: &str, start: usize) -> Scanned<'_> {
    let b = src.as_bytes();
    let end = run_until(b, start, |c| is_blank(c) || c == b'=')?;
    if b.get(end) == Some(&b'=') {
        Ok((Token::Key(&src[start..end]), end + 1))
    } else {
        Ok((Token::Word(&src[start..end]), end))
    }
}

/// Advances from `from` to the first byte that `ends` accepts, or to the end of the line.
/// A `"` on the way is an error, because quotes only start a value.
fn run_until(b: &[u8], from: usize, ends: impl Fn(u8) -> bool) -> Result<usize, LexError> {
    let mut i = from;
    while let Some(&c) = b.get(i) {
        if ends(c) {
            return Ok(i);
        }
        if c == b'"' {
            return Err(LexError::UnexpectedQuote { pos: i });
        }
        i += 1;
    }
    Ok(i)
}

/// A token must be followed by a blank or the end of the line.
fn expect_separator(b: &[u8], at: usize) -> Result<(), LexError> {
    match b.get(at) {
        Some(&c) if !is_blank(c) => Err(LexError::ExpectedSeparator { pos: at }),
        _ => Ok(()),
    }
}

fn skip_blanks(b: &[u8], mut p: usize) -> usize {
    while b.get(p).is_some_and(|&c| is_blank(c)) {
        p += 1;
    }
    p
}

fn is_blank(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

