// Scratch harness, not part of the repo.
// Compares the original tokenizer with the refactored one (exhaustively on short inputs)
// and times both on a synthetic dump.
#[path = "C:/Users/Jonas/AppData/Local/Temp/cc-agentic-fn8y9d07/repo/src/error.rs"]
mod error;
#[path = "C:/Users/Jonas/AppData/Local/Temp/cc-scratch-tok/orig/token.rs"]
mod old_token;
#[path = "C:/Users/Jonas/AppData/Local/Temp/cc-agentic-fn8y9d07/repo/src/token.rs"]
mod new_token;

use std::hint::black_box;
use std::time::Instant;

const ALPHABET: &[char] = &[' ', '\t', '[', ']', '"', '\\', '=', 'a', 'n', 't', 'q', 'é'];
const MAX_LEN: usize = 6;

fn old_out(line: &str) -> String {
    format!("{:?}", old_token::tokenize(line).collect::<Vec<_>>())
}

fn new_out(line: &str) -> String {
    format!("{:?}", new_token::tokenize(line).collect::<Vec<_>>())
}

fn exhaustive() -> (u64, u64) {
    let mut checked = 0u64;
    let mut mismatches = 0u64;
    let mut stack: Vec<String> = vec![String::new()];
    // Breadth-first over every string of length 0..=MAX_LEN.
    let mut level: Vec<String> = vec![String::new()];
    for _ in 0..MAX_LEN {
        let mut next = Vec::with_capacity(level.len() * ALPHABET.len());
        for s in &level {
            for &c in ALPHABET {
                let mut t = s.clone();
                t.push(c);
                next.push(t);
            }
        }
        stack.extend(next.iter().cloned());
        level = next;
    }
    for s in &stack {
        checked += 1;
        let a = old_out(s);
        let b = new_out(s);
        if a != b {
            mismatches += 1;
            if mismatches <= 10 {
                println!("MISMATCH {s:?}\n  old: {a}\n  new: {b}");
            }
        }
    }
    (checked, mismatches)
}

fn synthetic_dump() -> Vec<String> {
    let templates = [
        "[2024-05-01T12:00:00Z] level=info msg=\"disk 91% full\" user=ann retries= done",
        "[2024-05-01T12:00:01Z] level=warn msg=\"a \\\"quoted\\\" \\n value\" path=/var/log/x.log",
        "started worker-3 ok host=db\tport=5432",
        "[2024-05-01T12:00:02Z] level=error msg=\"unterminated",
        "key=b=c tail=\"x\"y ok",
        "[2024-05-01T12:00:03Z] a=1 b= c=\"\" d=\"esc\\q\" e=f",
    ];
    let mut lines = Vec::new();
    for i in 0..1_500_000usize {
        let t = templates[i % templates.len()];
        lines.push(format!("{t} seq={i}"));
    }
    lines
}

fn count_old(lines: &[String]) -> u64 {
    let mut n = 0u64;
    for line in lines {
        for tok in old_token::tokenize(line) {
            match tok {
                Ok(_) => n += 1,
                Err(_) => break,
            }
        }
    }
    n
}

fn count_new(lines: &[String]) -> u64 {
    let mut n = 0u64;
    for line in lines {
        for tok in new_token::tokenize(line) {
            match tok {
                Ok(_) => n += 1,
                Err(_) => break,
            }
        }
    }
    n
}

fn main() {
    let (checked, mismatches) = exhaustive();
    println!("exhaustive: checked {checked} strings (len <= {MAX_LEN}), mismatches {mismatches}");

    let lines = synthetic_dump();
    let bytes: usize = lines.iter().map(|l| l.len() + 1).sum();
    println!("bench: {} lines, {:.1} MB", lines.len(), bytes as f64 / 1e6);

    let (mut best_old, mut best_new) = (f64::MAX, f64::MAX);
    let (mut sum_old, mut sum_new) = (0u64, 0u64);
    for round in 0..7 {
        // Alternate order each round so neither side always runs first or cold.
        let (first, second) = if round % 2 == 0 { (0, 1) } else { (1, 0) };
        for which in [first, second] {
            let start = Instant::now();
            let n = if which == 0 {
                black_box(count_old(black_box(&lines)))
            } else {
                black_box(count_new(black_box(&lines)))
            };
            let secs = start.elapsed().as_secs_f64();
            if which == 0 {
                sum_old = n;
                best_old = best_old.min(secs);
            } else {
                sum_new = n;
                best_new = best_new.min(secs);
            }
        }
    }
    println!("tokens yielded: old {sum_old}, new {sum_new}");
    println!("best of 7: old {:.1} ms, new {:.1} ms, new/old {:.3}", best_old * 1e3, best_new * 1e3, best_new / best_old);
}

